/* PREPROCESS to prepare for analysis work */
%afi_caf_preprocess(?g_cas, ?analysisID);

/* ASSIGN CASLIBS */
libname Public cas caslib=Public;

cas  casuser  sessopts=(caslib=casuser timeout=1800 locale="en_US");
libname casuser cas caslib=casuser;

/* check all macros passed to the code */
/* %put &=g_p_diagNm.; */
/* %put &=g_p_diagDesc.; */
/* %put &=g_p_type.; */
/* %put &=g_p_email.; */
/* %put &=g_p_defType.; */
/* %put &=g_p_hierCd.; */
/* %put &=g_p_util_loc_cd.; */
/* %put &=g_p_inst_status.; */
/* %put &=g_p_frcstIntvl.; */
/* %put &=g_p_modelType.; */

/* SAS EF Script */

/*Database credentials*/
libname efdb postgres preserve_col_names=yes preserve_tab_names=yes connection=global
server="efcrnd15-pgfs-server.postgres.database.azure.com"
port=5432
database="postgres"
schema="tenant_ef" 
user="postgres"
pass="<REDACTED>"
dbconinit="select set_config('request.jwt.claim.userid', '&SYSUSERID', false)"
READ_ISOLATION_LEVEL= RC
update_isolation_level= rc
READ_LOCK_TYPE = ROW
UPDATE_LOCK_TYPE =ROW;

options nomprint nomlogic nosymbolgen nonotes nosource nosource2 nofullstimer;

/*macro location*/
%include '/opt/sas/viya/home/commonfiles/heshah/ucmacros_t/*.sas';
%include '/opt/sas/viya/home/commonfiles/heshah/ucmacros_final/*.sas';
%include '/opt/sas/viya/home/commonfiles/heshah/macros/*.sas';
libname efhelp "/opt/sas/viya/home/commonfiles/heshah/efsashelp";

/*locale*/
%global locale;
%let locale=en-US;

%macro sef_batch_diagnosis_aiot;
proc sql;

INSERT INTO efdb.sef_diagnose(
	diagnose_nm,
	diagnose_desc,
	diagnose_type_id,
	hierarchy_id,
	node_id,
	type,
	user_id,
	def_type,
	hierarchy_cd,
	util_loc_cd,
	latest_instance_status,
	forecast_intervals)
	VALUES (
		"&g_p_diagNm.", 	    /*diagnose_nm: (required) Unique name of the diagnose*/
		"&g_p_diagDesc.", 		            /*diagnose_desc: (optional) Description of the diagnosis*/
		1, 						            /*diagnose_type_id: (required) 1 for simple diagnosis, 0 for Multi-Zone Diagnosis(MZD)*/
		0,						            /*hierarchy_id:*/
		0,						            /*node_id:*/
		&g_p_type., 						            /*type: (required) 0 for Generation diagnosis,1 for Load diagnosis,2 for EV Diagnosis*/
		"&g_p_email.", 	            /*(optional) user_id*/
		"&g_p_defType.", 					            /*def_type: (required) D for Diagnosis,MZD for Multi-Zone Diagnosis*/
		"&g_p_hierCd.", 				            /*hierarchy_cd: (required) Name of the Hierarchy */
		"&g_p_util_loc_cd.", 					            /*util_loc_cd: (required) Utility location code (node) */
		0, 						            /*latest_instance_status: (optional) 0 indicates in progress,1 indicates successfull, 2 indicates error for latest run diagnosis instance*/
		&g_p_frcstIntvl.); 					            /*forecast_intervals: (optional) 60 by default,valid value can be (5,15,30,60,1440)*/
select max(diagnose_id) into:diagnose_id from efdb.sef_diagnose;

INSERT INTO efdb.sef_diagnose_instance (
    diagnose_id, 			
    instance_status,
	user_id,

	/* --------------- Model Selection --------------- */
    model_type, 

	/* --------------- Main --------------- */
	/* ----- Periods ----- */ 		
    train_start_date, 		
    holdout_start_date, 	
    holdout_end_date,
	sub_hour, 
    sub_date_offset,

	/* ----- Weights ------ */
	weight_num, 
    weight_lower, 
    weight_upper,

	/* --------------- MAPE --------------- */
	/* ----- Type ------ */
	mape,
	forecast_interval,
    measurement_type,

	/* ----- Weights ----- */
	w_hourly_mape, 
	w_daily_mape, 
    w_daily_peak_mape,
	w_monthly_mape,
	w_monthly_peak_mape,
	w_annual_mape, 
    w_annual_peak_mape,
	mape_improvement,
    w_interval_mape,

	/* --------------- Advanced --------------- */
	outlier_percent, 
    residual_hist_length, 
    combine_fcst,
    poly_order,
    ape_cutoff,
	two_stage,
	default_wthr_type_cd, 
    add_var, 
    add_class,
	add_interaction,
    include_temperature, 
    trend,

	/* --------------- System --------------- */
    num_cpu, 
    fix_date_holiday_list,

	/* --------------- Cleansing --------------- */
    cleansing,
    feature_selection_method, 
    numbuckets, 
    z_threshold, 
    impute_method, 
    k, 
    interp_method,

	/* --------------- Generation Diagnosis Parameters for DL Models (LSTM/CNN-LSTM) i.e model_type=DL --------------- */
	dl_model,
    include_irr, 
    poly_order_irr,
    learning_rate, 
    num_epochs, 
    batch_size, 
    no_of_neurons, 
    rolling_flag, 
    num_filters_cnn, 
    filter_width_cnn,
    filter_height_cnn, 
    num_lstm_layers_cnnlstm, 
    neurons_layer1_cnnlstm, 
    neurons_layer2_cnnlstm, 
    num_fc_layers,
    neurons_layer1_fc, 
    neurons_layer2_fc, 
    num_lstm_layers, 
    neurons_layer1_lstm, 
    neurons_layer2_lstm,
    neurons_layer3_lstm, 
    neurons_layer4_lstm, 
    neurons_layer5_lstm, 
    generation_input_type,

 	/* --------------- Price Diagnosis Parameters --------------- */
    target_var
)
VALUES (
    	&diagnose_id., 			/* diagnose_id: system generated for new diagnosis, if multiple instances need to be created use same diagnose_id on which instances needs to be created */
    	0, 						/* instance_status: (required) default should be 0(in progress), after run completion status would be 1(success)/2(error) */
		"&g_p_email.",	/* user_id (optional)*/

		/* --------------- Model Selection --------------- */
		"&g_p_modelType.", 			/* model_type: (default=CLASSICAL) Choose whether you want to use CLASSICAL or DL Models)*/

		/* --------------- Main --------------- */
		/* ----- Periods ----- */
		"01MAR2003"d, 			/* train_start_date (required) (DDMMMYYYY) Select the start date of the historical data to be used to train the diagnose model so that it selects the best model. */
    	"01MAR2004"d, 			/* holdout_start_date (required) (DDMMMYYYY) Select the start date of the holdout period. The holdout period is the period between the Holdout Start Date and the Holdout End Date. */
    	"01MAR2004"d,			/* holdout_end_date (required) (DDMMMYYYY) Select the end date of the holdout period. The holdout period is the period between the Holdout Start Date and the Holdout End Date. */
		7,						/* sub_hour: (default=7 min=1 max=24) Enter the hour for submission (usually 7). For example, 7 means 7 AM. */
    	1, 						/* sub_date_offset: (default=1) Enter the number of days (usually 1) between the date of submission and the date of forecast. */

		/* ----- Weights ------ */
		4,						/* weight_num: (default=4 min=1 max=4) Enter the number of weights utilized to calculate the weighted average temperature. The calculation is exponentially smoothed. */
    	0.8, 					/* weight_lower:(default=0.8 min=0.8 max=1) Enter the lower boundary of the weight utilized to calculate the exponentially smoothed temperature.  */
    	0.95, 					/* weight_upper: (default=0.95 min=0.8 max=1) Enter the upper boundary of the weight utilized to calculate the exponentially smoothed temperature.  */

		/* --------------- MAPE --------------- */
		/* ----- Type ------ */
		"interval_mape", 		/* mape: (required) (default=interval_mape) Enter the criterion for selecting the best ( champion ) model. (choices=hourly_me hourly_mae hourly_mape daily_me daily_mae daily_mape daily_peak_me daily_peak_mae daily_peak_mape monthly_me monthly_mae monthly_mape monthly_peak_me monthly_peak_mae monthly_peak_mape annual_me  annual_mae annual_mape annual_peak_me annual_peak_mae) */
		60, 					/* forecast_interval: (required) default should be 60, valid values can be in 5,15,30,60,1440(daily) */
    	"POWER", 				/* measurement_type: (required) ENERGY or POWER*/

		/* ----- Weights ----- */
		0, 						/* w_hourly_mape: (required) (default=1 min=0 max=1) Weighted Hourly Mean Absolute Percentage Error*/
    	0, 						/* w_daily_mape: (required) (default=0 min=0 max=1) Weighted Daily Mean Absolute Percentage Error*/
    	0, 						/* w_daily_peak_mape: (required) (default=0 min=0 max=1) Weighted Daily Peak Mean Absolute Percentage Error*/
		0, 						/* w_monthly_mape: (required) (default=0 min=0 max=1) Weighted Monthly Mean Absolute Percentage Error */
		0,						/* w_monthly_peak_mape: (required) (default=0 min=0 max=1) Weighted Monthly Peak Mean Absolute Percentage Error */
    	0, 						/* w_annual_mape: (required) (default=0 min=0 max=1) Weighted Annual Mean Absolute Percentage Error */
    	0, 						/* w_annual_peak_mape: (required) (default=0 min=0 max=1) Weighted Annual Peak Mean Absolute Percentage Error */
		0.0001, 				/* mape_improvement: default=0.0001 min=0 max=1) Only if the model MAPE improvement is higher than the entered value should the forecasting improvement be considered significant. */
		1, 						/* w_interval_mape: (required) */

		/* --------------- Advanced --------------- */
		0.001,					/* outlier_percent: (default=0.001) (required for CLASSICAL models) Enter the percentage of observations that are to be considered as outliers.  */
		504, 					/* residual_hist_length: (default=504) (required for CLASSICAL models) Choose the length of time during which to calculate the residual used in the two-stage model (integer value with unit of hour). */
    	1234,					/* combine_fcst: (default=1234) (required for CLASSICAL two-stage models) This parameter controls which two-stage model(s) will be included for calculating the combined forecast. The value for this parameter will be various combinations of 1, 2, 3 and 4. 1=GLM_ARIMA (auto regressive integrated moving average) 2=GLM_ESM (exponential smoothing modeling) 3=GLM_UCM (unobserved components modeling) 4=GLM_NN (neural network) */
		2,						/* poly_order: (default=2) Control using 2nd or 3rd order polynomial of the temperature variables in the model. The value of this parameter should be either 2 or 3.*/
    	0.5, 					/* ape_cutoff: (default=0.5) The APE Cutoff determines which observations are put into the outlier table. Observations with absolute percentage error greater than this threshold will be put into the table. */
    	"NO", 					/* two_stage: (default=NO) Enter YES to run the two-stage model. Enter NO to run the one-stage model. */
		"TEMPF", 				/* default_wthr_type_cd: (default=TEMPF) Specifies the type of data contained in the WTHR_NO field of the weather data source file. */
		"", 					/* add_var: (Optional) Variables that you specify in this field are used in the MODEL statement of PROC GLM as independent effects.  */
    	"", 					/* add_class: (Optional) Add a class variable. Variables that you specify in this field are used in the CLASS statement of PROC GLM as additional class variables */
		"",						/* add_interaction: (Optional) Specify modeling and class variables to study potential interactive effects on each other. You can enter any combination of independent variables (indicated by an asterisk) that affect the output variable.Example: For load data, Season*Humidity.For generation data, Azimuth_Angle*Air_Quality_Index.*/
    	"YES", 					/* include_temperature: Include weather data in a forecast. Default is YES */
    	"YES", 					/* trend: Include the trend data. Default is YES. */

		/* --------------- System --------------- */
    	2, 						/* num_cpu: (default=2) Select the number of available CPU cores to define how many parallel processes should be run. */
    	"1 5 8 10", 			/* fix_date_holiday_list: (default=1 5 8 10) Using a numeric code, specify the holidays whose calendar date does not differ from year to year. Separate each numeric code with a blank  */

		/* --------------- Cleansing --------------- */
		"NO",					/* cleansing: (required) Include cleansing data along with imputation. Default is NO ,fill other parameter otherwise */
		"",						/* feature_selection_method: RF/RPCA */
    	.,						/* numbuckets: Specifies how many bins the historical temperature or irradiance data is divided into for detecting outliers. Binning helps identify anomalies that are relevant within each time interval.Valid range: 10â€“150.*/
    	.,						/* z_threshold: Indicates how far the value deviates from the mean and it is measured in standard deviations.*/
    	"",						/* impute_method: Defines the algorithm that estimates and replaces outliers or missing values. Available options depend on whether Include temperature (for load data) or Include irradiance (for generation data) is Yes or No.When the setting is Yes, the following options are displayed, for both load and generation data: KNN,TREE When the setting is No, the following options are displayed:GLM,interpolation*/
    	.,						/* k: Note: This setting is displayed only when Include temperature or Include irradiance is Yes and Imputation method is set to KNN.Specifies the number of nearest neighbors used in KNN imputation. A higher value reduces sensitivity to local fluctuations but can generalize more.Valid range: 1-500.*/
    	"",						/* interp_method: Fills missing values by estimating values along a line or curve between the surrounding known points.*/


		/* --------------- Generation Diagnosis Parameters for DL Models (LSTM/CNN-LSTM) i.e model_type=DL --------------- */
		.,						/* dl_model: 0 for LSTM,1 for CNN-LSTM,2 for BOTH*/
    	.,						/* include_irr: (required=True) (default=1) Irradiance values help determine the efficiency of a solar cell or panel in converting sunlight into electricity. Irradiance is a key factor that influences the overall performance of solar power systems.*/
    	.,						/* poly_order_irr: (required=True) (default=2) Note: This setting is displayed only if Include irradiance is yes. This value specifies the polynomial degree used to analyze irradiance and its effect on the model. This involves examining how different degrees of polynomial equations capture the relationship between irradiance and the model's outcomes.*/
    	.,						/* learning_rate: Optimizer step size for updating model weights.*/
    	.,						/* num_epochs: An epoch is a single run through the entire data set in a learning process. It consists of one or more batches, where each batch is a group of data samples. In an epoch, every sample in the training data set gets an opportunity to adjust the internal model parameters once.Specify the number of epochs.For load forecasting, 75.For solar forecasting, 150.*/
    	.,						/* batch_size: Specify the number of samples that are passed through the network at a time before the model's weights are updated during training. This influences training speed and memory usage.*/
    	.,						/* no_of_neurons: The number of neurons (perceptrons) in a fully connected (FC) layer.*/
    	.,						/* rolling_flag: Specify whether to generate a diagnosis one unit at a time and use the resulting forecast for the next time interval in the sequence (for example, the next 15-minute forecast).Note: This option is useful if your data is very volatile. Otherwise, it is best to select No to save time and resources.*/
    	.,						/* num_filters_cnn:Filters, or kernels, are multi-dimensional data (tensors) used in the convolution layer of a neural network to extract specific features from input data. In CNNs, filters are typically 2-D and characterized by their width and height.The number of filters affects how complex the model is and its ability to understand patterns. It influences how well the model can extract features and make accurate predictions.*/
    	.,						/* filter_width_cnn:This setting determines how wide to make the filters that scan the input data before sending it to the LSTM layers. This affects how well the model can understand patterns over time and relationships between different locations at the same time.*/
    	.,						/* filter_height_cnn:This setting determines how high to make the filters that scan the input data before sending it to the LSTM layers. This affects how well the model can understand patterns over time and relationships between different locations at the same time.*/
    	.,						/* num_lstm_layers_cnnlstm: The number of layers that are used for forecasting.The purpose of an LSTM layer is to learn long-term dependencies within time series and sequence data. */
    	.,						/* neurons_layer1_cnnlstm: The neurons present in the first layer of the CNN-LSTM model.*/
    	.,						/* neurons_layer2_cnnlstm: The neurons present in the second layer of the CNN-LSTM model.*/
    	.,						/* num_fc_layers: The number of fully connected (FC) layers.  An FC layer connects a flattened input to all neurons and it is used at the end of a CNN to optimize objectives like class scores or regression values.*/
    	.,						/* neurons_layer1_fc: The neurons present in the first layer of the fully connected (FC) layer.*/
    	.,						/* neurons_layer2_fc: The neurons present in the second layer of the fully connected (FC) layer.*/
    	.,						/* num_lstm_layers: The number of layers that are used for forecasting.The purpose of an LSTM layer is to learn long-term dependencies within time series and sequence data. */
    	.,						/* neurons_layer1_lstm: The neurons present in the first layer of the fully connected (FC) layer of the CNN-LSTM model.*/
    	.,						/* neurons_layer2_lstm: The neurons present in the second layer of the fully connected (FC) layer of the CNN-LSTM model.*/
    	.,						/* neurons_layer3_lstm: The neurons present in the third layer of the fully connected (FC) layer of the CNN-LSTM model.*/
    	.,						/* neurons_layer4_lstm: The neurons present in the fourth layer of the fully connected (FC) layer of the CNN-LSTM model.*/
    	.,						/* neurons_layer5_lstm: The neurons present in the fifth layer of the fully connected (FC) layer of the CNN-LSTM model.*/
    	"",						/* generation_input_type: The load data type used for generation: Power (megawatts) or Energy (megawatt hours).*/

		/* --------------- Price Diagnosis Parameters --------------- */
    	"",						/* target_var: The variabe for which forcast has to be generated.*/
);
select max(instance_id) into:id from efdb.sef_diagnose_instance;
quit;

%let instance_id=&id.;
%put "inserted id= &instance_id.";
%sef_diag_wrap_allmodels(&instance_id.,testing=NO);

%mend sef_batch_diagnosis_aiot;

/*Invoke Diagnosis Call*/
%sef_batch_diagnosis_aiot;

/* Create lookup table */

proc sql; 
    create table work.diag_lkup as 
    select t1.*, t2.instance_id, t2.model_type
    from efdb.sef_diagnose as t1 left join efdb.sef_diagnose_instance as t2 on t1.diagnose_id=t2.diagnose_id;
quit; 

/* Save Output in CAS */

/* To finish the analysis specific code, setup the info needed for */
/* the postprocess.                                                */

/* Provide any output tables to be persisted and used later.       */
/* Postprocess will promote and save the output tables in the      */
/* QASANLOUT global caslib using a standard naming convention of   */
/* <analysis_type>_tablename_<shortid>                             */
/* For example: CARS_filtered_ABC123                               */
/*              CARS_complete_ABC123                               */
%let g_num_output_tables = 5;
%let g_output_table_1 = efdb.sef_diagnose;
%let g_output_table_2 = work.diag_lkup; 
%let g_output_table_3 = efdb.diag_results;
%let g_output_table_4 = efdb.diag_results_all;
%let g_output_table_5 = efdb.diag_stat;


/* Provide any output variable to be used later.                   */
/* Postprocess will save these variables into metadata so they can */
/* be used in the VA output or in later analysis steps             */
/* For example: filtered_count = 20                                */
%let g_num_output_vars = 3;
%let g_output_var_1 = g_p_diagNm;
%let g_output_var_2 = g_p_email;
%let g_output_var_3 = diagnose_id;

/* *************************************************************** */
/* END ANALYSIS SPECIFIC PROGRAMMING                               */
/* *************************************************************** */


/* PREPROCESS to save analysis WORK                                */
%afi_caf_postprocess;

/* PREPROCESS to prepare for analysis work */
%afi_caf_preprocess(?g_cas, ?analysisID);

/* ASSIGN CASLIBS */
libname Public cas caslib=Public;

cas  casuser  sessopts=(caslib=casuser timeout=1800 locale="en_US");
libname casuser cas caslib=casuser;

/* SAS EF Script */

/*Database credentials*/
libname efdb postgres preserve_col_names=yes preserve_tab_names=yes connection=global
server="efcrnd15-pgfs-server.postgres.database.azure.com"
port=5432
database="postgres"
schema="tenant_ef" 
user="postgres"
pass="<REDACTED>"
dbconinit="select set_config('request.jwt.claim.userid', '&SYSUSERID', false)"
READ_ISOLATION_LEVEL= RC
update_isolation_level= rc
READ_LOCK_TYPE = ROW
UPDATE_LOCK_TYPE =ROW;

options nomprint nomlogic nosymbolgen nonotes nosource nosource2 nofullstimer;

%include '/opt/sas/viya/home/commonfiles/heshah/ucmacros_t/*.sas';
%include '/opt/sas/viya/home/commonfiles/heshah/ucmacros_final/*.sas';
%include '/opt/sas/viya/home/commonfiles/heshah/macros/*.sas';
libname efhelp "/opt/sas/viya/home/commonfiles/heshah/efsashelp";

%global locale;
%let locale=en-US;

%macro sef_batch_forecast;
proc sql;
INSERT INTO efdb.sef_forecast (
    /* --------------- Properties --------------- */
    instance_id,
    diagnose_id,
    forecast_name,
    forecast_description,
    forecast_status,
    user_id,

    /* --------------- Type: STF/VSTF/MTLTLF --------------- */
    forecast_type,

    /* --------------- Main --------------- */
    /* --------------- STF --------------- */
    historical_start_dt,
    forecast_start_dt,
    forecast_end_dt,

    /* --------------- VSTLF --------------- */
    forecast_start_hour,
    forecast_length,
    perform_optimize_forecast,

    /* --------------- MTF --------------- */
    mtltlf_forecast_type,
    mtlt_assumption,
    num_scenarios,
    scenarios,
    hist_load_start_dt,
    hist_load_end_dt,
    hist_t_start,
    hist_t_end,
    run_mtltlf_naive_model,
    run_mtltlf_recency_model,
    run_mtltlf_weekend_model,
    run_mtltlf_holiday_model,
    mtf_agg_fcst,
    mtf_agg_interval,
    mtf_agg_acc_method
)
VALUES (
    /* --------------- Properties --------------- */
    &g_p_instanceID.,                 /*instance_id: (required) diagnosis instance_id on which this forecast needs to be created*/
    &g_p_diagnosisID.,                 /*diagnose_id: (required) diagnose_id of the instance oin which forecast is created*/
    "&g_p_forecastnm.",   /*forecast_name: (required) Unique Name of the forecast*/
    "&g_p_forecastDesc.",            /*forecast_description: Description fo the Forecast*/
    0,                      /*forecast_status: (required) 0 indicates in progress,1 indicates successfull,2 indicates error*/
    "&g_p_email.",   /*user_id: (optional)*/

    /* --------------- Type: STF/VSTF/MTLTLF --------------- */
    2,                      /*forecast_type: (required) (1->STF,2->VSTLF,0->MTLTLF)*/

    /* --------------- Main --------------- */
    /* ----- VSTLF and STLF ----- */
    "01MAR2003"d,           /*historical_start_date:(required for vstlf or stlf) Select the start date for historical date that is to be used for creating the forecast.*/
    "02MAR2004"d,           /*forecast_start_date:(required for vstlf or stlf) Select the start date for the forecast horizon.*/

	/* ----- STLF ----- */
    .,                     /*forecast_end_date:(required for stlf) Select the end date for the forecast horizon*/

    /* ----- VSTLF ----- */
    1,                      /*forecast_start_hour: Select the start hour for the forecast horizon (between 1 and 24).*/
    24,                     /*forecast_length: Select the length for the forecast horizon, which is the number of hours to be forecasted (integer value).*/
    "YES",                  /*perform_optimize_forecast: default=YES (YES or NO)*/

    /* ----- MTLFLF ----- */
    "",                     /*mtltlf_forecast_type: (default=Probabilistic) Probabilistic, Point*/
    .,                      /*mtlt_assumption: This parameter is used to set how GXP (gross x product) will be included in the forecast model. The values can be 1, 2 or 3 which represent one of the following: 1=Include GXP as Trend. 2=Include GXP as Trend and Interact GXP with other factors. 3=Divide Load by GXP*/
    .,                      /*num_scenarios: Enter the number of economy scenarios to be used (an integer between 1 and 7, with a default of 7)*/
    "",                      /*scenarios: The number that represents the specific economic scenarios to use. e integers between 0 and 6, separated by spaces.*/
							/*For example, 0 denotes the base scenario. 0 2 5 denotes the base scenario, scenario 2, and scenario 5. */
    .,                     /*hist_load_start_dt: (required for MTLFLF) Select the start date for history.*/
    .,                     /*hist_load_end_dt: (required for MTLFLF) Select the end date for history*/
    .,                     /*hist_t_start: (required for MTLFLF) Select the start date for the historical temperature data which should be equal to or greater than the start date of the utility’s temperature data.*/
    .,                     /*hist_t_end: (required for MTLFLF) Select the end date for the historical temperature data*/
    "",                     /*run_mtltlf_naive_model: (required for MTLFLF) yes or no*/
    "",                     /*run_mtltlf_recency_model: (required for MTLFLF) yes or no*/
    "",                     /*run_mtltlf_weekend_model: (required for MTLFLF)yes or no*/
    "",                     /*run_mtltlf_weekend_model: (required for MTLFLF) yes or no*/
    .,                      /*mtf_agg_fcst: (required for MTLFLF) 1-> for aggregate 0-> no aggregation enabled on forecast results*/
    .,                      /*mtf_agg_interval: (required if mtf_agg_fcst is 1, aggregation interval: 1:Daily,2:Weekly,3:Monthly,4:Quarterly . valid values range=(1-4) */
    .                      	/*mtf_agg_acc_method: (required if mtf_agg_fcst is 1, accumulation method: 1:Total,2:average,3:minimum,4:maximum,5:median . valid values range=(1,5)*/
);
select max(forecast_id) into:id from efdb.sef_forecast;
quit;

%sef_fcst_wrap_allmodels(&id.,testing=NO);

%mend sef_batch_forecast;

%sef_batch_forecast;


/* copy of efdb.fcst_results_with_name with shorter name */

data work.fcst_results_wNm;
    set efdb.fcst_results_with_name;
run;

/* Save Output in CAS */

/* To finish the analysis specific code, setup the info needed for */
/* the postprocess.                                                */

/* Provide any output tables to be persisted and used later.       */
/* Postprocess will promote and save the output tables in the      */
/* QASANLOUT global caslib using a standard naming convention of   */
/* <analysis_type>_tablename_<shortid>                             */
/* For example: CARS_filtered_ABC123                               */
/*              CARS_complete_ABC123                               */
%let g_num_output_tables = 4;
%let g_output_table_1 = efdb.fcst_results;
%let g_output_table_2 = efdb.fcst_results_all;
%let g_output_table_3 = efdb.fcst_stat;
%let g_output_table_4 = work.fcst_results_wNm;

/* Provide any output variable to be used later.                   */
/* Postprocess will save these variables into metadata so they can */
/* be used in the VA output or in later analysis steps             */
/* For example: filtered_count = 20                                */
%let g_num_output_vars = 3;
%let g_output_var_1 = g_p_forecastnm;
%let g_output_var_2 = g_p_forecastDesc;
%let g_output_var_3 = forecast_id;
/* *************************************************************** */
/* END ANALYSIS SPECIFIC PROGRAMMING                               */
/* *************************************************************** */


/* PREPROCESS to save analysis WORK                                */
%afi_caf_postprocess;
